#!/usr/bin/env python3
"""
Write a minimal gene file, config/genes/<gene>.yaml, from UniProt: the
reviewed human entry for the gene symbol. That is enough for the variant
atlas (constraint, NMD map, UniProt domain annotations). Curated sections
(domains, calibration, pathway) are left empty with instructions.

Usage: make_gene_config.py --gene CEP57 --out config/genes/cep57.yaml
"""
import argparse
import csv
import datetime
import io
import os
import sys
import urllib.parse
import urllib.request

TEMPLATE = """\
# Gene knowledge: {gene} ({name}).
# Generated by bin/make_gene_config.py on {date} from UniProt {acc}
# (reviewed, human). Edit freely; it is not regenerated once it exists.
#
# Optional sections, each switching on an analysis (see bub1b.yaml):
#   domains: path/to/domains.tsv       curated map instead of UniProt's
#   stability_features: [...]          features where instability = dose defect
#   calibration: [{{variant: X123Y, class: destabilising|stable}}, ...]
#   pathway: [{{symbol: ..., desired: up|down|no_inhibit, tier: "1", rationale: ...}}]
#   named_drugs: [...]

gene: {gene}
uniprot: {acc}
disorder: ""
"""


def lookup(gene):
    q = f"gene_exact:{gene} AND organism_id:9606 AND reviewed:true"
    url = ("https://rest.uniprot.org/uniprotkb/search?format=tsv"
           "&fields=accession,gene_primary,protein_name&query=" + urllib.parse.quote(q))
    try:
        with urllib.request.urlopen(url, timeout=60) as r:
            rows = list(csv.DictReader(io.StringIO(r.read().decode()), delimiter="\t"))
    except Exception as e:
        sys.exit(f"ERROR: UniProt lookup failed for {gene}: {e}")
    hits = [r for r in rows if (r.get("Gene Names (primary)") or "").upper() == gene.upper()]
    if len(hits) != 1:
        sys.exit(f"ERROR: expected one reviewed human UniProt entry for {gene}, "
                 f"found {len(hits)}: write config/genes/{gene.lower()}.yaml by hand")
    return hits[0]["Entry"], hits[0]["Protein names"].split(" (")[0]


def write(gene, out):
    acc, name = lookup(gene)
    os.makedirs(os.path.dirname(out) or ".", exist_ok=True)
    with open(out, "w") as fh:
        fh.write(TEMPLATE.format(gene=gene.upper(), name=name, acc=acc,
                                 date=datetime.date.today().isoformat()))
    print(f"wrote {out}: {gene.upper()} = UniProt {acc} ({name})", file=sys.stderr)


if __name__ == "__main__":
    a = argparse.ArgumentParser()
    a.add_argument("--gene", required=True)
    a.add_argument("--out", required=True)
    args = a.parse_args()
    write(args.gene, args.out)
